=== radio-input-group ===
/**
 * @component radio-input-group
 * @summary A single-select radio `<fieldset>`, plain or as a connected segmented toggle.
 * @modifier -layout-columns — Lay the radios out in columns.
 * @modifier -layout-inline — Lay the radios out inline.
 * @modifier -required — Mark the group as required.
 * @modifier -variant-toggle — Lay the child toggles out as a segmented control (only the selected segment fills).
 * @pseudo ::after — Renders the decorative required-field asterisk after the legend text when the group is required.
 * @accessibility Renders a native `<fieldset>` with a `<legend>` that names the group; the child radios share one `name`, so only one can be selected at a time.
 * @example
 * <fieldset class="pfx-radio-input-group -variant-toggle">
 *   <legend>T-shirt size</legend>
 *   <label class="pfx-radio -variant-toggle"><input type="radio" name="size" checked> Small</label>
 *   <label class="pfx-radio -variant-toggle"><input type="radio" name="size"> Medium</label>
 *   <label class="pfx-radio -variant-toggle"><input type="radio" name="size"> Large</label>
 * </fieldset>
 * @structure
 * .pfx-radio-input-group.-variant-toggle {
 *   legend {}
 *   .pfx-radio.-variant-toggle {
 *     input {}
 *   }
 * }
 * @related radio — The individual control this group collects.
 * @related form-field-group — The general wrapper for grouping and laying out fields.
 */
.pfx-radio-input-group {
  display: flex;
  flex-direction: column;
  gap: var(--instui-component-form-field-layout-gap-inputs);
  min-inline-size: 0;
  margin: 0;
  padding: 0;
  border: 0;
}
.pfx-radio-input-group > legend {
  padding: 0;
  margin-block-end: var(--instui-component-form-field-layout-gap-primitives);
  color: var(--instui-component-form-field-layout-text-color);
  font-family: var(--instui-component-form-field-layout-font-family);
  font-weight: var(--instui-component-form-field-layout-font-weight);
  font-size: var(--instui-component-form-field-layout-font-size);
  line-height: var(--instui-component-form-field-layout-line-height);
}
.pfx-radio-input-group.-required > legend::after {
  content: "*";
  margin-inline-start: 0.25rem;
  color: var(--instui-component-form-field-layout-asterisk-color);
}
/* simple variant: -layout-columns/-inline flow the standard radios into a wrapping row */
.pfx-radio-input-group.-layout-columns,
.pfx-radio-input-group.-layout-inline {
  flex-flow: row wrap;
  align-items: center;
  column-gap: var(--instui-spacing-space-md);
}
.pfx-radio-input-group.-layout-columns > legend,
.pfx-radio-input-group.-layout-inline > legend {
  flex-basis: 100%;
}
/* toggle variant: lay the child .instui-radio.-variant-toggle segments out flush in a row — no gap and
   no borders, matching InstUI's colSpacing="none". The visible spacing between labels is each segment's
   own inline padding; only the checked segment paints a pill. Lift the focused segment so its focus ring
   isn't clipped by a neighbour. */
.pfx-radio-input-group.-variant-toggle {
  flex-flow: row wrap;
  align-items: center;
  gap: 0;
}
.pfx-radio-input-group.-variant-toggle > legend {
  flex-basis: 100%;
}
.pfx-radio-input-group.-variant-toggle > .pfx-radio:has(input:focus-visible) {
  z-index: 1;
}
=== form-field-group legend ===
