1	<script setup lang="ts">
2	import { computed, ref } from "vue";
3	import { useData } from "vitepress";
4	import { CDN_PICKER_DEFAULTS, type CdnPickerStrings } from "../cdn";
5	import manifest from "../generated/cdn-manifest.json";
6	
7	type ManifestComponent = { name: string; needsIcons: boolean };
8	// Alphabetical for findability (the manifest is in load order).
9	const components = [...(manifest.components as ManifestComponent[])].sort((a, b) =>
10	  a.name.localeCompare(b.name),
11	);
12	
13	// Localized labels from the active locale's themeConfig.cdnPicker, falling back to English defaults.
14	const { theme } = useData();
15	const t = computed<CdnPickerStrings>(() => ({
16	  ...CDN_PICKER_DEFAULTS,
17	  ...(theme.value as { cdnPicker?: Partial<CdnPickerStrings> }).cdnPicker,
18	}));
19	
20	const selected = ref<Set<string>>(new Set());
21	const allComponents = ref(false);
22	const tokenSheet = ref<"lean" | "full">("lean");
23	const includeBase = ref(false);
24	const format = ref<"link" | "import">("link");
25	const copied = ref(false);
26	
27	function toggle(name: string): void {
28	  const next = new Set(selected.value);
29	  if (next.has(name)) next.delete(name);
30	  else next.add(name);
31	  selected.value = next;
32	  copied.value = false;
33	}
34	
35	const chosen = computed(() => components.filter((c) => selected.value.has(c.name)));
36	// "All" uses the whole `components.css` barrel; otherwise the checked per-component sheets.
37	const active = computed(() => (allComponents.value ? components : chosen.value));
38	const hasSelection = computed(() => allComponents.value || chosen.value.length > 0);
39	// The lean token sheet omits icons, so any active icon-using component needs component-icons.css. The
40	// full sheet already carries every icon.
41	const needsIconSheet = computed(
42	  () => tokenSheet.value === "lean" && active.value.some((c) => c.needsIcons),
43	);
44	
45	const combineUrl = computed(() => {
46	  // Track the latest release (no version pin) — pin yourself for production. jsDelivr serves raw file
47	  // paths (it ignores the package `exports` map), and every sheet ships under `dist/`.
48	  const c = "npm/@pantoken/components/dist";
49	  const files = [
50	    `npm/@pantoken/css/dist/${tokenSheet.value === "lean" ? "style.lean.css" : "style.css"}`,
51	  ];
52	  if (includeBase.value) files.push(`${c}/base.css`);
53	  if (needsIconSheet.value) files.push(`${c}/component-icons.css`);
54	  if (allComponents.value) files.push(`${c}/components.css`);
55	  else for (const comp of chosen.value) files.push(`${c}/${comp.name}.css`);
56	  return `https://cdn.jsdelivr.net/combine/${files.join(",")}`;
57	});
58	
59	const output = computed(() =>
60	  format.value === "link"
61	    ? `<link rel="stylesheet" href="${combineUrl.value}">`
62	    : `@import url("${combineUrl.value}");`,
63	);
64	
65	async function copy(): Promise<void> {
66	  try {
67	    await navigator.clipboard.writeText(output.value);
68	    copied.value = true;
69	    setTimeout(() => (copied.value = false), 1500);
70	  } catch {
71	    // Clipboard blocked — the code stays selectable in the block.
72	  }
73	}
74	</script>
75	
76	<template>
77	  <div
78	    class="cdn-picker instui-view -background-secondary -border-radius-large -border-width-small instui-p-md"
79	  >
80	    <fieldset class="instui-form-field-group cdn-picker__group">
81	      <legend>{{ t.componentsLabel }}</legend>
82	      <label class="instui-checkbox cdn-picker__all">
83	        <input type="checkbox" v-model="allComponents" />
84	        <span>{{ t.allComponents }}</span>
85	      </label>
86	      <div
87	        class="cdn-picker__components instui-view -background-primary -border-radius-medium -border-width-small instui-p-sm"
88	        :class="{ 'cdn-picker__components--disabled': allComponents }"
89	      >
90	        <label v-for="c in components" :key="c.name" class="instui-checkbox">
91	          <input
92	            type="checkbox"
93	            :checked="selected.has(c.name)"
94	            :disabled="allComponents"
95	            @change="toggle(c.name)"
96	          />
97	          <span>{{ c.name }}</span>
