import json, glob, os, re
roots=["packages","formats","platforms","renderers","bundlers","design","ai","plugins/pantoken","plugins/postcss","plugins/typedoc","plugins/vite","tools"]
false_pkgs=[]
for r in roots:
    for p in sorted(glob.glob(f"{r}/*/package.json")):
        d=json.load(open(p))
        if d.get("private") or not str(d.get("name","")).startswith("@pantoken/"): continue
        if d.get("sideEffects") is False:
            false_pkgs.append(os.path.dirname(p))
# scan each package's src entry for top-level side-effecting statements
susp_re=re.compile(r'^(?!\s*(import|export|const|let|var|function|class|type|interface|enum|async|//|/\*|\*|})\b)(\S.*\b(globalThis|window|document|customElements|process\.|console\.)\b.*)$')
hits=[]
for d in false_pkgs:
    for entry in ["src/index.ts","src/index.tsx","src/index.mts"]:
        fp=os.path.join(d,entry)
        if os.path.exists(fp):
            for i,line in enumerate(open(fp),1):
                if susp_re.match(line):
                    hits.append(f"{fp}:{i}: {line.strip()[:80]}")
            break
print(f"false-set packages scanned: {len(false_pkgs)}")
print(f"suspicious top-level side-effect lines: {len(hits)}")
for h in hits[:20]: print("  ", h)
PY

